import{_ as l,o as a,c as o,ag as i}from"./chunks/framework.D2veAa-g.js";const h=JSON.parse('{"title":"存储管理","description":"","frontmatter":{"title":"存储管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/存储管理.md","filePath":"综合知识/系统基础/操作系统/存储管理.md","lastUpdated":null}'),s={name:"综合知识/系统基础/操作系统/存储管理.md"};function e(r,t,d,n,c,u){return a(),o("div",null,[...t[0]||(t[0]=[i('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 分区存储管理（固定/可变/可重定位，分配算法）</li><li>[ ] 分页存储管理 → 详见子文件</li><li>[ ] 分段存储管理</li><li>[ ] 段页式存储管理</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="分区存储管理" tabindex="-1">分区存储管理 <a class="header-anchor" href="#分区存储管理" aria-label="Permalink to &quot;分区存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：分区管理是&quot;整存&quot; — 固定分区产生内部碎片，可变分区产生外部碎片。</p></blockquote><p><strong>整存</strong>，将进程所需内存整体一起分配。</p><table tabindex="0"><thead><tr><th>方式</th><th>特点</th></tr></thead><tbody><tr><td>固定分区</td><td>静态分区，产生内部碎片</td></tr><tr><td>可变分区</td><td>动态分区，产生外部碎片</td></tr><tr><td>可重定位分区</td><td>移动已分配区域合并碎片，仅在外部请求无法满足时触发</td></tr></tbody></table><p><strong>可变分区分配算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>策略</th></tr></thead><tbody><tr><td>首次适应法</td><td>从头查找，找到第一个 &gt;= 所需空间的空间块</td></tr><tr><td>最佳适应法</td><td>空闲块按大小排序，找最接近的</td></tr><tr><td>最差适应法</td><td>找最大的空闲块，防止产生过多细小碎片</td></tr><tr><td>循环首次适应法</td><td>从上次分配位置继续查找，不每次从头开始</td></tr></tbody></table><h3 id="分页存储管理" tabindex="-1">分页存储管理 <a class="header-anchor" href="#分页存储管理" aria-label="Permalink to &quot;分页存储管理&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/分页存储管理.html">架构师-备考 综合知识-系统基础-操作系统-分页存储管理</a></p><p>逻辑页分为页号和页内地址，通过页表查询页号对应的物理块号。相关概念：页面置换算法（最优算法、先进先出、最近最少使用）、快表。</p><h3 id="分段存储管理" tabindex="-1">分段存储管理 <a class="header-anchor" href="#分段存储管理" aria-label="Permalink to &quot;分段存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：段表包含<strong>段长和基址</strong>。偏移 &gt; 段长即为<strong>地址越界</strong>。</p></blockquote><p>将进程空间按逻辑整体分段，段表包含<strong>段长和基址</strong>两个属性来确定逻辑段在物理段中的位置。</p><ul><li>优点：多道程序共享内存，各段修改互不影响</li><li>缺点：内存利用率低，内存碎片浪费大</li></ul><blockquote><p>地址越界判断：逻辑地址 (段号, 偏移) 中偏移 &gt; 段长 则为越界。常见错误原因是<strong>逻辑地址转换物理地址时地址越界</strong>，根源通常是数组下标越界没有检查。</p></blockquote><h3 id="段页式存储管理" tabindex="-1">段页式存储管理 <a class="header-anchor" href="#段页式存储管理" aria-label="Permalink to &quot;段页式存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>先分段，后分页</strong>。空间浪费小、共享容易、保护容易、能动态链接。</p></blockquote><ul><li>优点：空间浪费小、存储共享容易、存储保护容易、能动态链接</li><li>缺点：管理软件复杂度和开销增加，执行速度下降</li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q2] 段式存储-越界判断</strong></p><p>假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（ ）不能转换为对应的物理地址。</p><ul><li>A. (0，790)和(2，88)</li><li>B. (1，30)和(3，290)</li><li>C. (2，88)和(4，98)</li><li>D. (0，810)和(4，120)</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：段0段长800，偏移810&gt;800越界；段4段长100，偏移120&gt;100越界。</p></div></details><hr><p><strong>[Q3] 段式存储-越界原因</strong></p><p>假设系统采用段式存储管理方法。逻辑地址不能转换为对应的物理地址；不能转换的原因是进行（ ）。</p><ul><li>A. 除法运算时除数为零</li><li>B. 算术运算时有溢出</li><li>C. 逻辑地址到物理地址转换时地址越界</li><li>D. 物理地址到逻辑地址转换时地址越界</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：偏移&gt;段长→地址越界，发生在逻辑地址→物理地址转换过程中。</p></div></details><hr><p><strong>[Q31] 段式存储-越界根源</strong></p><p>假设系统采用段式存储管理方法，逻辑地址不能转换为对应的物理地址，可能的原因是（ ）。</p><ul><li>A. 数组下标运算没有检查是否越界</li><li>B. 除零错</li><li>C. 内存段分配失败</li><li>D. 页面不在内存中</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：段越界的常见根源是程序数组下标越界未检查，导致段内偏移超出段长。</p></div></details><hr><p><strong>[Q51] 段页式地址</strong></p><p>在段页式存储管理中，逻辑地址由（ ）组成。</p><ul><li>A. 段号、页号和页内偏移量</li><li>B. 段号和段内偏移量</li><li>C. 页号和页内偏移量</li><li>D. 段号和页号</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：段页式=先分段再分页，逻辑地址=段号+页号+页内偏移。</p></div></details>',40)])])}const b=l(s,[["render",e]]);export{h as __pageData,b as default};
